var EXTRA=[{"dot": "gray", "j": "Orthop Surg", "h": "Revisione asettica con una sola coltura inattesa positiva: antibiotico prolungato e fallimento", "v": "Coorte retrospettiva con pochi casi: l'associazione fra terapia lunga e fallimento può riflettere la gravità dell'infezione e non la durata; gli stessi autori lo dicono.", "pmid": "42906634", "doi": "10.1111/os.70452", "temi": ["revisione", "infezione", "colture", "antibiotici"]}, {"dot": "gray", "j": "Arthroplast Today", "h": "Classificazione di Dorr inversa: qualità ossea del femore distale sulla radiografia laterale", "v": "Retrospettivo monocentrico: la conicità della corticale anteriore si associa alla densità ossea alla DXA; serve una validazione esterna prima di guidare la scelta dell'impianto.", "pmid": "42903444", "doi": "10.1016/j.artd.2026.102179", "temi": ["protesi", "qualità ossea", "femore distale", "radiografia"]}, {"dot": "gray", "j": "Clin Orthop Surg", "h": "Protesi su ginocchio varo: togliere gli osteofiti posteriori allarga lo spazio mediale", "v": "Misure intraoperatorie in una serie retrospettiva con un solo tipo di protesi posteriore stabilizzata; non dice nulla sull'esito clinico.", "pmid": "42877329", "doi": "10.4055/cios26098", "temi": ["protesi", "gap", "osteofiti", "bilanciamento"]}, {"dot": "gray", "j": "Int J Sports Phys Ther", "h": "Ritorno allo sport dopo LCA: la scoping review sugli strumenti psicologici", "v": "Mappa degli strumenti usati, con l'ACL-RSI come il più frequente; gli autori ammettono che nessuno strumento basta e che non è provato che usarne più d'uno cambi l'esito.", "pmid": "42893311", "doi": "10.26603/001c.171296", "temi": ["LCA", "ritorno allo sport", "psicologia", "ACL-RSI"]}, {"dot": "gray", "j": "J Orthop Res", "h": "Cuscinetto adiposo infrapatellare dopo chirurgia del ginocchio nei corridori: più piccolo nelle donne", "v": "Analisi trasversale esplorativa: il volume minore non si associa ai sintomi femororotulei; non dice se sia l'intervento a ridurlo.", "pmid": "42885727", "doi": "10.1002/jor.70300", "temi": ["cuscinetto adiposo", "sesso", "corridori", "femororotuleo"]}, {"dot": "gray", "j": "J Knee Surg", "h": "Agonisti del GLP-1 prima della protesi: meno infarti e trombosi dopo l'intervento", "v": "Coorte retrospettiva su dati TriNetX con appaiamento per propensity score; è un'associazione e non prova un effetto del farmaco, con prescrizione come unica misura dell'esposizione.", "pmid": "42880346", "doi": "10.1055/a-2982-7440", "temi": ["protesi", "GLP-1", "trombosi", "TriNetX"]}, {"dot": "gray", "j": "Cureus", "h": "Vescicole extracellulari intra-articolari nell'artrosi: serie di casi di un solo studio privato", "v": "Serie di casi di livello IV su prodotti non approvati dalla FDA per uso intra-articolare, senza gruppo di controllo: non permette di giudicare l'efficacia.", "pmid": "42890957", "doi": "10.7759/cureus.117960", "temi": ["artrosi", "infiltrazioni", "vescicole extracellulari", "biologici"]}, {"dot": "gray", "j": "J Orthop Surg Res", "h": "Morte in ospedale dopo revisione protesica: l'infezione periprotesica è l'indicazione prevalente", "v": "Coorte monocentrica dei soli decessi, in prevalenza anziani: descrive e non confronta, quindi non dice quanto rischio aggiunga l'infezione rispetto alle altre indicazioni.", "pmid": "42864644", "doi": "10.1186/s13018-026-07259-4", "temi": ["revisione", "infezione periprotesica", "mortalità", "anca e ginocchio"]}];
var SCOPERTE=[{"t": "Robot per protesi di ginocchio che segue i movimenti dell'osso: niente fissatore dell'arto", "v": "Ingegneria dei dispositivi (Chinese Journal of Medical Instrumentation, MicroPort NaviBot, Suzhou): un sistema di tracciamento in tempo reale per cui il braccio robotico segue i piccoli spostamenti dell'osso durante il taglio. Vale la deviazione perché mostra un'idea diversa dai fissatori dell'arto; l'abstract non riporta numeri né pazienti, ed è un lavoro dell'azienda produttrice.", "pmid": "42865046", "doi": "10.12455/j.issn.1671-7104.250661", "temi": ["robotica", "protesi", "bioingegneria", "Cina"]}, {"t": "Agopuntura dell'occhio più elettroagopuntura nel dolore da artrosi: il modello nel ratto", "v": "Studio di laboratorio (Journal of Pain Research, Hangzhou, medicina tradizionale cinese): 36 ratti con artrosi indotta, la combinazione alza la soglia del dolore più della sola elettroagopuntura e riduce l'espressione di TRPV1 nel midollo spinale. Vale la deviazione perché mostra come si ragiona sul dolore da artrosi in un altro mondo; è un esperimento sul ratto e non dice nulla sul paziente.", "pmid": "42893105", "doi": "10.2147/JPR.S628497", "temi": ["agopuntura", "artrosi", "dolore", "mondo orientale"]}];
var SOC={"1": {"video": "Menisco: la radice riparata regge, ma il menisco si sposta. Uno studio giapponese su 54 ginocchia ha operato la radice posteriore del menisco insieme a un'osteotomia.\n\nLa riparazione risultava continua in circa nove casi su dieci con entrambe le tecniche e i punteggi sono molto migliorati; il menisco però è uscito dalla sua sede, da circa metà a oltre il sessanta per cento della larghezza.\n\nIl limite: confronto per periodi successivi, un terzo dei pazienti escluso e nessun gruppo con la sola osteotomia.\nFonte: PubMed, PMID 42903211.", "linkedin": "Radice meniscale con osteotomia: la continuità della sutura non è la funzione. Coorte giapponese (J Exp Orthop, 2026; 54 ginocchia): continuità 89,3% con pull-out transtibiale e 88,5% con all-inside, ma estrusione mediale da 49,6% a 62,0% e da 48,8% a 68,8%.\n\nIl limite: disegno sequenziale, potenza di 76% per un effetto grande, nessun gruppo con la sola osteotomia.\nFonte: PubMed, PMID 42903211.", "instagram": "Menisco e osteotomia\n\nLa sutura della radice tiene in nove casi su dieci, ma il menisco si sposta verso l'esterno.\n\nPochi pazienti e nessun confronto con la sola osteotomia.\nFonte: PubMed, PMID 42903211.", "pazienti": "Menisco riparato con osteotomia: la riparazione regge, ma il menisco si sposta un po'. Uno studio giapponese su 54 ginocchia ha seguito pazienti operati al menisco e all'asse della gamba.\n\nI punteggi di dolore e funzione sono migliorati molto e la riparazione era intatta in quasi tutti; il menisco però è uscito un poco dalla sua sede.\n\nLo studio è piccolo e non confronta con la sola correzione dell'asse: la scelta spetta al chirurgo, caso per caso.\nFonte: PubMed, PMID 42903211."}};
var SOCV={"1": {"video": {"chir": ["Riparazione della radice meniscale posteriore mediale con osteotomia tibiale alta: coorte retrospettiva giapponese su J Exp Orthop, 54 ginocchia, pull-out transtibiale contro all-inside, controllo di 24-48 mesi, testo completo letto.", "Continuità ripristinata nell'89,3% e nell'88,5%; Lysholm 96,3 ± 4,5 e 92,8 ± 8,1, senza differenze. Ma l'estrusione mediale sale da 49,6% a 62,0% con la pull-out (p=0,003) e da 48,8% a 68,8% con l'all-inside (p<0,001), con differenza fra i gruppi non significativa (p=0,190).", "Limiti: disegno sequenziale, 23 ginocchia su 77 escluse, potenza dichiarata del 76% per un effetto grande, nessun braccio con la sola osteotomia. La continuità della sutura non equivale al recupero della funzione meniscale.\nFonte: PubMed, PMID 42903211."], "misto": ["Riparare la radice del menisco insieme a un'osteotomia della tibia: che cosa succede dopo due-quattro anni? Uno studio giapponese su 54 ginocchia ha confrontato due modi di fissare il menisco.", "La sutura risultava integra alla risonanza in circa nove casi su dieci con entrambi i modi, e i punteggi di funzione sono molto migliorati. Il menisco però si è spostato verso l'esterno, da circa metà a oltre il sessanta per cento della sua larghezza.", "Il limite: il confronto è per periodi successivi, circa un terzo dei pazienti è uscito dall'analisi e non c'è un gruppo con la sola osteotomia.\nFonte: PubMed, PMID 42903211."], "pazienti": ["Menisco riparato insieme a una correzione dell'asse della gamba: com'è andata? Uno studio giapponese ha seguito 54 ginocchia per due-quattro anni.", "Dolore e funzione sono migliorati molto e la riparazione era intatta in quasi tutti; il menisco però si è spostato un poco verso l'esterno.", "Lo studio è piccolo e non confronta con la sola correzione dell'asse: la scelta spetta al chirurgo, caso per caso.\nFonte: PubMed, PMID 42903211."]}, "linkedin": {"chir": ["Radice meniscale e osteotomia: continuità 89,3% (pull-out) e 88,5% (all-inside), Lysholm 96,3 ± 4,5 e 92,8 ± 8,1 in 54 ginocchia (J Exp Orthop, 2026).", "Estrusione mediale 49,6% → 62,0% (p=0,003) e 48,8% → 68,8% (p<0,001): la continuità non coincide con la funzione.", "Limiti: sequenziale, 23 ginocchia su 77 escluse, potenza 76%, nessun braccio con la sola osteotomia.\nFonte: PubMed, PMID 42903211."], "misto": ["Riparazione della radice del menisco con osteotomia: in 54 ginocchia la sutura tiene, ma il menisco si sposta (J Exp Orthop, 2026).", "I punteggi di funzione sono molto migliorati con entrambe le tecniche; la larghezza del menisco fuori sede è passata da circa metà a oltre il sessanta per cento.", "Il limite: pazienti confrontati per periodi successivi, senza un gruppo con la sola osteotomia.\nFonte: PubMed, PMID 42903211."], "pazienti": ["Menisco riparato con correzione dell'asse: lo studio giapponese su 54 ginocchia mostra buon recupero e un menisco un po' spostato.", "La riparazione risultava intatta in quasi tutti i pazienti.", "Lo studio è piccolo: la scelta spetta al chirurgo, caso per caso.\nFonte: PubMed, PMID 42903211."]}, "instagram": {"chir": ["Radice meniscale + osteotomia", "Continuità circa 89%, estrusione da 49,6% a 62,0% e da 48,8% a 68,8%.", "Sequenziale, potenza 76%, senza braccio con la sola osteotomia.\nFonte: PubMed, PMID 42903211."], "misto": ["Menisco e osteotomia", "La sutura tiene in nove casi su dieci, ma il menisco si sposta verso l'esterno.", "Pochi pazienti e nessun confronto con la sola osteotomia.\nFonte: PubMed, PMID 42903211."], "pazienti": ["Menisco riparato", "La riparazione regge, ma il menisco si sposta un poco: lo dice uno studio giapponese su 54 ginocchia.", "Studio piccolo: la scelta spetta al chirurgo.\nFonte: PubMed, PMID 42903211."]}, "reel": {"chir": ["[Testo a schermo] Radice meniscale: continuità non è funzione", "Continuità 89%, estrusione 49,6% → 62,0%.", "Sequenziale, potenza 76%.\nFonte: PubMed, PMID 42903211."], "misto": ["[Testo a schermo] Menisco riparato: regge, ma si sposta", "Sutura intatta in 9 casi su 10.", "Studio piccolo, senza controllo.\nFonte: PubMed, PMID 42903211."], "pazienti": ["[Testo a schermo] Menisco riparato: com'è andata?", "La riparazione regge, il menisco si sposta un poco.", "Studio piccolo: decide il chirurgo.\nFonte: PubMed, PMID 42903211."]}}};
var TAGS={"1": {"linkedin": "#Ortopedia #Menisco #Ginocchio", "instagram": "#ortopedia #ginocchio #menisco #osteotomia #radicemeniscale #chirurgiadelginocchio #medicinadellosport #ortopediaticino #ticino #medicinabasatasulleprove #salute", "kw": "menisco, radice meniscale, osteotomia tibiale alta, ginocchio, chirurgia artroscopica"}};
var NLB={"1": {"prof": ["Radice meniscale con osteotomia: l'estrusione cresce con pull-out e con all-inside", "Coorte retrospettiva sequenziale giapponese (J Exp Orthop, 2026; 54 ginocchia, riparazione della radice posteriore mediale con osteotomia tibiale alta). Continuità ripristinata nell'89,3% con pull-out transtibiale e nell'88,5% con all-inside; Lysholm 96,3 ± 4,5 e 92,8 ± 8,1. Il rapporto di estrusione mediale sale da 49,6% a 62,0% (p=0,003) e da 48,8% a 68,8% (p<0,001), senza differenza significativa fra le tecniche.", "Nota critica: disegno sequenziale, 23 ginocchia su 77 escluse, potenza di 76% per un effetto grande, nessun gruppo con la sola osteotomia; la continuità della sutura non equivale al recupero della funzione meniscale."], "mix": ["Radice del menisco e osteotomia: la sutura tiene, ma il menisco esce di sede", "In 54 ginocchia operate in Giappone con riparazione della radice del menisco e osteotomia della tibia, la sutura risultava integra alla risonanza in circa nove casi su dieci con entrambe le tecniche, e i punteggi di funzione sono molto migliorati. Tuttavia il menisco si è spostato verso l'esterno dell'articolazione più di prima, da circa metà a oltre il sessanta per cento della sua larghezza.", "Nota sul limite: il confronto non è casuale ma per periodi successivi, e un terzo circa dei pazienti è uscito dall'analisi; non si sa quanto del risultato venga dall'osteotomia."], "paz": ["Menisco riparato con osteotomia: la sutura regge, ma il menisco si sposta", "In un gruppo di pazienti operati al ginocchio in Giappone, la parte posteriore del menisco è stata riparata insieme a una correzione dell'asse della gamba. I punteggi di dolore e funzione sono migliorati molto, e la riparazione risultava intatta in quasi tutti; il menisco però si è spostato un po' verso l'esterno.", "Lo studio ha limiti: pochi pazienti, nessun confronto con la sola correzione dell'asse. Il tipo di intervento lo decide il chirurgo con il paziente."], "kw": "menisco, radice meniscale, osteotomia tibiale, ginocchio"}, "2": {"prof": ["Osteotomia tibiale alta: la sovracorrezione riduce il recupero nell'artrosi iniziale", "Coorte retrospettiva giapponese (Arch Orthop Trauma Surg, 2026; 181 ginocchia, controllo minimo 2 anni). Nei KL ≤ 2 la sovracorrezione (linea di carico ≥ 70%) riduce il miglioramento del FJS-12 (β −10,49; IC 95% da −20,46 a −0,53) rispetto all'allineamento ottimale; nei KL ≥ 3 l'allineamento non è associato agli esiti.", "Nota critica: livello IV, centro singolo, ginocchia bilaterali trattate come indipendenti; è un'associazione, e la sottocorrezione non significativa non prova che sia innocua."], "mix": ["Osteotomia del ginocchio: correggere troppo non aiuta se l'artrosi è iniziale", "In 181 ginocchia operate con osteotomia tibiale alta, chi aveva un'artrosi ancora poco avanzata ha recuperato meno quando l'asse della gamba era stato corretto più del necessario. Nell'artrosi avanzata la misura della correzione non è risultata associata al recupero.", "Nota sul limite: lo studio è retrospettivo, di un solo centro; mostra un'associazione, non che la correzione eccessiva causi il minor recupero."], "paz": ["Osteotomia del ginocchio: la misura della correzione conta soprattutto se l'artrosi è iniziale", "In uno studio giapponese su 181 ginocchia, chi era operato con artrosi ancora iniziale ha recuperato meno se l'asse della gamba era stato spostato troppo. Con artrosi più avanzata la differenza non si è vista.", "È uno studio di un solo centro e guarda al passato: la pianificazione della correzione resta una decisione del chirurgo, caso per caso."], "kw": "osteotomia tibiale alta, ginocchio, artrosi, allineamento"}, "3": {"prof": ["Innesto nel LCA e ritorno allo sport: l'autoinnesto supera l'alloinnesto, nessun autoinnesto prevale", "Revisione narrativa (Curr Rev Musculoskelet Med, 2026). Ritorno allo sport circa 65-73% a tre anni e 83-90% negli atleti d'élite e delle superiori; nei giovani attivi più ritorno e meno revisioni con gli autoinnesti che con gli alloinnesti; le metanalisi di RCT non stabiliscono la superiorità di un singolo autoinnesto, quadricipite compreso.", "Nota critica: revisione narrativa, metodo di ricerca non riportato nell'abstract, preferenza dichiarata dell'autore senior per quadricipite o patellare; effetti e intervalli non riportati."], "mix": ["Legamento crociato: nessun innesto prevale sugli altri per tornare allo sport", "Una rassegna sulla ricostruzione del legamento crociato anteriore conclude che nei giovani attivi i tendini del paziente stesso permettono di tornare allo sport più spesso e con meno nuove operazioni rispetto al tendine di donatore. Fra i tendini del paziente, nessuno risulta chiaramente superiore agli altri.", "Nota sul limite: è una rassegna narrativa e non una sintesi sistematica; il ritorno allo sport non è l'unico esito che conta."], "paz": ["Legamento crociato: la scelta del tendine va fatta caso per caso", "Una rassegna di studi sul legamento crociato anteriore indica che, nei giovani sportivi, un tendine preso dal paziente stesso riporta più spesso allo sport di quello di un donatore. Tra i tendini del paziente nessuno è risultato adatto a tutti.", "Il limite: è una rassegna senza numeri nuovi. La scelta spetta al chirurgo, in base a età, sport e anatomia."], "kw": "legamento crociato anteriore, innesto, ritorno allo sport, ginocchio"}, "4": {"prof": ["Lussazione del ginocchio: lesione dell'arteria poplitea nello 0,38% dei ricoveri, con complicanze molto più frequenti", "Coorte retrospettiva su database americano (J Invest Surg, 2026; circa 211.108 ricoveri per trauma grave del ginocchio). Prevalenza ponderata della lesione dell'arteria poplitea 0,38% (IC 95% 0,33-0,42%), lussazione come predittore più forte; dopo appaiamento complicanze chirurgiche aOR 4,50 (IC 95% 3,40-5,97), riammissione a 30 giorni aOR 1,81 (IC 95% 1,21-2,70).", "Nota critica: database amministrativo, senza dati su polsi, indice caviglia-braccio o tempo alla diagnosi; associazioni non causali, gravità del trauma non del tutto controllata."], "mix": ["Trauma grave del ginocchio: la lesione dell'arteria è rara ma pesa molto", "In un'analisi su circa 211.000 ricoveri negli Stati Uniti per lussazione, lesioni dei legamenti o fratture attorno al ginocchio, una lesione dell'arteria poplitea è stata registrata in meno di un caso su duecento. Quando c'era, le complicanze e la degenza erano molto più gravi, soprattutto dopo una lussazione.", "Nota sul limite: i dati vengono da registri amministrativi e non dicono come è stata fatta la diagnosi; sono associazioni e non cause."], "paz": ["Lussazione del ginocchio: i vasi vanno controllati", "In un'analisi di molti ricoveri americani per gravi traumi del ginocchio, la lesione dell'arteria dietro al ginocchio era rara, ma quando c'era portava più complicazioni e ricoveri più lunghi. Per questo, dopo una lussazione, si controllano sempre i vasi.", "I dati vengono da registri e hanno limiti: non dicono quanto sia grave il singolo caso. Le decisioni spettano al medico curante e al chirurgo."], "kw": "lussazione del ginocchio, arteria poplitea, trauma, ginocchio"}, "5": {"prof": ["LCA con legamento artificiale a doppio fascio: pivot-shift negativo a 8,5 mesi, studio troppo breve", "Studio comparativo retrospettivo cinese (Zhongguo Xiu Fu Chong Jian Wai Ke Za Zhi, 2026; 45 pazienti, 16 doppio fascio e 29 fascio singolo, controllo medio 8,5 mesi). Pivot-shift positivo in 0 contro 3 ginocchia di grado I (non significativo); ritorno allo sport più alto nel doppio fascio (p<0,05, percentuali non riportate); intervento più lungo.", "Nota critica: gruppi non randomizzati, controllo di 8,5 mesi, nessuna tenuta del legamento artificiale a lungo termine; il confronto sul pivot-shift non può escludere un RR fino a 4,59."], "mix": ["Crociato con legamento artificiale: promettente a pochi mesi, ma è troppo presto", "In 45 pazienti operati in Cina, una ricostruzione del crociato con un legamento artificiale a due fasci ha dato una buona stabilità e un ritorno allo sport più frequente rispetto a un solo fascio, dopo in media otto mesi e mezzo.", "Nota sul limite: i gruppi non sono stati formati a caso e il controllo è troppo breve per sapere come tiene un legamento artificiale negli anni."], "paz": ["Crociato: un legamento artificiale a due fasci dà buoni risultati iniziali", "In uno studio cinese su 45 pazienti, un legamento artificiale a due fasci ha dato buona stabilità del ginocchio nei primi mesi.", "Lo studio è piccolo e breve: non dice come tenga il legamento dopo anni. La scelta della tecnica spetta al chirurgo."], "kw": "legamento crociato anteriore, legamento artificiale, doppio fascio, ginocchio"}, "6": {"prof": ["Estrusione meniscale: la mappa circonferenziale su RM 3D è riproducibile", "Studio di fattibilità (J Orthop Res, 2026; 20 pazienti, 3 lettori). Variabilità intra-lettore DS 0,2 mm (ripetibilità 0,6 mm), fra lettori DS 0,5 mm (riproducibilità 1,4 mm); concordanza del 98% con la misura coronale 2D al corpo.", "Nota critica: 20 pazienti e nessun esito clinico; la tolleranza di 1,4 mm è larga rispetto alle soglie cliniche; analisi regionale solo esplorativa."], "mix": ["Menisco spostato: la risonanza 3D permette di misurarlo lungo tutto il bordo", "Un gruppo americano ha messo a punto un modo di misurare quanto il menisco esce dalla sua sede lungo tutto il bordo dell'articolazione, e non solo in un'immagine. Tre lettori hanno ottenuto misure molto simili, e al centro del menisco il metodo concorda con la misura abituale.", "Nota sul limite: sono solo venti pazienti e non si sa ancora se la misura regionale preveda come andrà il ginocchio."], "paz": ["Menisco: una nuova misura dello spostamento alla risonanza", "Un gruppo di ricercatori ha provato un modo di misurare quanto il menisco si sposta, usando la risonanza in tre dimensioni. Le misure di tre lettori diversi erano molto simili.", "È uno studio su venti pazienti e riguarda la ricerca: non cambia le cure di oggi."], "kw": "menisco, estrusione, risonanza magnetica, ginocchio"}, "7": {"prof": ["Riparazione del LCA con bandelletta ileotibiale: solo un modello a elementi finiti", "Simulazione (Front Bioeng Biotechnol, 2026; un ginocchio virtuale da TC). Innesto da 1,5 mm in tunnel da 6 mm: deformazione massima circa 1,1%, stress 5,69 MPa, lassità anteroposteriore 3,5 mm contro 3,2 mm del ginocchio intatto; innesto da 2 mm in tunnel da 5 mm: 11,62 MPa e 2,5%.", "Nota critica: un solo modello, osso rigido, carico statico di 100 N, nessuna validazione su cadavere o su pazienti."], "mix": ["Rinforzo del crociato con un tendine della coscia: per ora solo al computer", "In una simulazione al computer di un ginocchio, un nastro sottile preso dal fascio laterale della coscia ha dato una lassità vicina a quella del ginocchio sano se il tunnel nell'osso era abbastanza largo. Con tunnel stretti lo sforzo sul nastro cresceva molto.", "Nota sul limite: è un solo ginocchio virtuale, senza pazienti né esperimenti su cadavere."], "paz": ["Crociato: una simulazione al computer sul rinforzo con un nastro di tendine", "In una simulazione al computer di un ginocchio, un nastro sottile di tendine ha dato una stabilità simile a quella del ginocchio sano, a condizione che il tunnel fosse abbastanza largo.", "È solo una simulazione su un ginocchio virtuale: non è stata provata su pazienti."], "kw": "legamento crociato, riparazione, simulazione, ginocchio"}, "8": {"prof": ["Revisione protesica asettica: nessuno studio di livello I sulla scelta dell'impianto", "Scoping review (PLoS One, 2026; 121 articoli e 6 rapporti di registri su 7.096 articoli e 155 rapporti). Solo 22 studi (18%) su sole prime revisioni asettiche elettive; 45 serie retrospettive (37%) e 41 confronti retrospettivi (34%), nessuno di livello I, 5 studi (4%) con controllo di almeno 10 anni.", "Nota critica: è una mappa delle prove, non una sintesi di effetto: non valuta il bias e non dice quale impianto scegliere."], "mix": ["Protesi da rifare: sulla scelta dell'impianto le prove sono ancora deboli", "Una mappatura della letteratura sulla scelta dell'impianto quando una protesi di ginocchio va sostituita, senza infezione, ha trovato soprattutto serie retrospettive e nessuno studio di livello più alto. Pochi studi seguono i pazienti per dieci anni o più.", "Nota sul limite: la mappa mostra dove mancano le prove, ma non indica quale impianto sia preferibile."], "paz": ["Protesi di ginocchio da sostituire: mancano ancora studi di buona qualità sulla scelta dell'impianto", "Una rassegna della letteratura ha cercato quali studi esistono sulla scelta dell'impianto quando una protesi di ginocchio va rifatta. Gli studi sono quasi tutti retrospettivi.", "La rassegna non dice quale impianto sia preferibile. La scelta spetta al chirurgo, in base alla situazione di ogni persona."], "kw": "protesi di ginocchio, revisione protesica, impianto, ginocchio"}};
var ARTICLES=[{n:1,mono:"m-jeo",dot:"orange",sec:"res",j:"J Exp Orthop",h:"Radice meniscale con osteotomia: continuità ripristinata nell'89%, ma l'estrusione cresce con entrambe le suture",v:"Coorte retrospettiva sequenziale giapponese (Sapporo): 54 ginocchia, riparazione della radice posteriore mediale con osteotomia tibiale alta, pull-out transtibiale (28) contro sutura all-inside (26), 24-48 mesi. Continuità ripristinata nell'89,3% e nell'88,5%, Lysholm 96,3 ± 4,5 e 92,8 ± 8,1, nessuna differenza fra le tecniche. Il rapporto di estrusione mediale però sale da 49,6% a 62,0% (p=0,003) con la pull-out e da 48,8% a 68,8% (p<0,001) con l'all-inside; la differenza fra i gruppi a fine controllo non è significativa (p=0,190).",ax:"Fujie, Yasuda, Yabuuchi, Ebata, Inoue, Iwasaki, Kondo",date:"ott 2026",meta:"coorte retrospettiva sequenziale (l'abstract la chiama prospettica), livello III, 54 ginocchia in 52 pazienti, 24-48 mesi",pmid:'42903211',doi:'10.1002/jeo2.70956',journal:"Journal of experimental orthopaedics",authors:"Fujie Y, Yasuda K, Yabuuchi K, Ebata T, Inoue M, Iwasaki N, Kondo E",design:"Coorte retrospettiva sequenziale in un ospedale di Sapporo, un solo chirurgo senior: dal 2018 al marzo 2020 pull-out transtibiale (tunnel di 4,5 mm, tre suture sul bottone), poi sutura all-inside con FAST-FIX 360 e una terza sutura capsulare; in tutti osteotomia tibiale alta (apertura mediale se la correzione è sotto 10°, a V rovesciata sopra). Artroscopia di controllo a circa 1 anno, RM con estrusione misurata col metodo di Costa modificato, Lysholm e KOOS. Letto il testo completo (PMC).",pop:"77 ginocchia eleggibili (50-70 anni, KL 1-3 con varismo, intervento entro 3 mesi dal dolore); 15 perse al controllo e 8 senza RM, restano 54 ginocchia in 52 pazienti: 28 pull-out e 26 all-inside. Età 61,7 ± 7,6 e 62,3 ± 8,5 anni; controllo a 37,1 e 33,8 mesi (abstract e testo danno dispersioni diverse per la durata del controllo).",results:"Radice ripristinata alla RM: 89,3% (pull-out) e 88,5% (all-inside); alla seconda artroscopia discontinuità in 3 ginocchia per gruppo (10,7% e 11,5%), con tessuto fibroso lasso nelle altre. Estrusione mediale: 49,6% → 62,0% (p=0,003) e 48,8% → 68,8% (p<0,001); aumento di almeno 10 punti nel 57,1% contro il 73,1% (differenza non significativa). Lysholm 96,3 ± 4,5 e 92,8 ± 8,1; KOOS migliorato in tutte le sottoscale senza differenze fra i gruppi; KL non progredito; nessuna complicanza.",concl:"Gli autori: con l'osteotomia le due tecniche danno miglioramenti radiologici e clinici comparabili a 2-4 anni, nonostante l'aumento dell'estrusione; la continuità alla sutura non coincide con il recupero della funzione meniscale e l'estrusione andrebbe misurata negli studi futuri.",limits:"Disegno sequenziale retrospettivo, due periodi e due durate di controllo: periodo e tecnica sono confusi · 23 ginocchia su 77 (30%) escluse per perdita al controllo o RM mancante; potenza dichiarata di soli 76% per un effetto grande (differenza minima rilevabile d=0,76), quindi l'estrusione potrebbe differire fra le tecniche · nessun gruppo con la sola osteotomia: non si sa quanto dell'esito venga dalla sutura.",perte:"Arancione: la tua pull-out transtibiale è una delle due tecniche, e regge: continuità 89,3% e punteggi alti con l'osteotomia. Ma la continuità non è la funzione: l'estrusione cresce di 12,4 punti con la pull-out e di 20,0 con l'all-inside (confronto muto), quindi non c'è prova che la tecnica scelta cambi l'estrusione. Alimenta la T2b. Cosa fare: referta l'estrusione sulla RM di controllo e non usare la continuità della sutura come prova di funzione."},{n:2,mono:"m-gray",dot:"green",sec:"res",j:"Arch Orthop Trauma Surg",h:"Osteotomia tibiale alta: la sovracorrezione peggiora gli esiti solo nell'artrosi iniziale",v:"Coorte retrospettiva giapponese (Tokyo Women's Medical University): 181 ginocchia con osteotomia tibiale alta, controllo minimo 2 anni. Nell'artrosi iniziale (KL ≤ 2; 112 ginocchia) la sovracorrezione (linea di carico ≥ 70%) riduce il miglioramento del FJS-12 (β −10,49; IC 95% da −20,46 a −0,53) rispetto all'allineamento ottimale; nell'artrosi avanzata (KL ≥ 3; 69) l'allineamento non è associato agli esiti.",ax:"Itou, Itoh, Kuwashima, Oda, Okazaki",date:"ott 2026",meta:"coorte retrospettiva monocentrica, livello IV, 181 ginocchia (112 KL ≤ 2, 69 KL ≥ 3)",pmid:'42907576',doi:'10.1007/s00402-026-06540-9',journal:"Archives of orthopaedic and trauma surgery",authors:"Itou J, Itoh M, Kuwashima U, Oda T, Okazaki K",design:"Coorte retrospettiva monocentrica di osteotomie tibiali alte, ad apertura o a chiusura, dal 2017 al 2023, con bersaglio di linea di carico al 62,5% su radiografia sotto carico dell'intero arto. Sovracorrezione definita come linea di carico ≥ 70%; regressioni multivariate su ΔFJS-12 e ΔKOOS, regressione logistica su MCID e PASS; ogni ginocchio trattato come unità indipendente. Letto solo l'abstract.",pop:"181 ginocchia operate nel 2017-2023: 112 con artrosi iniziale (KL ≤ 2) e 69 con artrosi avanzata (KL ≥ 3), con caratteristiche di base comparabili; età, sesso e tipo di osteotomia per gruppo non riportati nell'abstract.",results:"Artrosi iniziale: la sovracorrezione riduce ΔFJS-12 (β −10,49; IC 95% da −20,46 a −0,53) e ΔKOOS Sport, e la probabilità di raggiungere MCID e PASS; la sottocorrezione non mostra un'associazione significativa. Artrosi avanzata: nessuna associazione fra allineamento e miglioramento dei punteggi né con MCID e PASS. Numeri di MCID e PASS non riportati nell'abstract.",concl:"Gli autori: la sovracorrezione si associa a un miglioramento minore di FJS-12 e KOOS Sport nell'artrosi iniziale, non in quella avanzata.",limits:"Retrospettivo, centro singolo, livello IV: un'associazione, non una prova che la sovracorrezione causi il peggioramento · ginocchia bilaterali trattate come indipendenti, cosa che può restringere gli intervalli · nessuna sottocorrezione significativa non vuol dire che sia innocua: il numero per categoria non è nell'abstract.",perte:"Verde: tocca la tua osteotomia. Il dato utile è che il bersaglio conta di più dove l'articolazione è ancora poco consumata, e che la linea di carico ≥ 70% si associa a un recupero minore. Cosa fare: con artrosi iniziale non pianificare correzioni che portino la linea di carico oltre il 70%; è un'associazione retrospettiva, da non usare come regola rigida. Non muove le tensioni."},{n:3,mono:"m-gray",dot:"green",sec:"res",j:"Curr Rev Musculoskelet Med",h:"Scelta dell'innesto nel LCA e ritorno allo sport: l'autoinnesto batte l'alloinnesto, nessun autoinnesto prevale",v:"Revisione narrativa americana (Missouri): il ritorno allo sport dopo LCA è circa 65-73% a tre anni e 83-90% negli atleti d'élite e delle superiori. Nei giovani attivi gli autoinnesti si associano a più ritorno e meno revisioni degli alloinnesti; le metanalisi di RCT non stabiliscono la superiorità di nessun autoinnesto. Il quadricipite è descritto come versatile, con poca morbilità del prelievo; l'autore senior preferisce quadricipite o patellare per gli atleti ad alta richiesta.",ax:"Jackson, Childers, Mowers, Boley, Ryan, DeFroda, Nuelle",date:"ott 2026",meta:"revisione narrativa, evidenza bassa, quattro innesti (patellare, ischiocrurali, quadricipite, alloinnesto)",pmid:'42905316',doi:'10.1007/s12178-026-10061-8',journal:"Current reviews in musculoskeletal medicine",authors:"Jackson GR, Childers JT, Mowers CC, Boley JS, Ryan P, DeFroda SF, Nuelle C",design:"Revisione narrativa sull'influenza della scelta dell'innesto nel LCA sul ritorno allo sport, limitata ai quattro innesti più usati: tendine patellare con osso, ischiocrurali, tendine del quadricipite e alloinnesto. Strategia di ricerca e criteri di inclusione non riportati nell'abstract. Letto solo l'abstract.",pop:"Non applicabile (rassegna); il numero di studi inclusi non è riportato nell'abstract.",results:"Ritorno allo sport circa 65-73% a tre anni, 83-90% negli atleti d'élite e delle superiori; negli adulti giovani attivi più ritorno e meno revisioni con gli autoinnesti che con gli alloinnesti; nessuna superiorità stabilita fra gli autoinnesti nelle metanalisi di RCT. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: per il ritorno allo sport la letteratura sostiene l'autoinnesto rispetto all'alloinnesto nei giovani attivi, senza un autoinnesto adatto a tutti; la scelta va individualizzata (età, sport, anatomia, rischio di nuova lesione).",limits:"Revisione narrativa senza metodo di ricerca nell'abstract: nessuna garanzia che gli studi siano stati scelti in modo completo · l'autore senior dichiara una preferenza (quadricipite o patellare): possibile orientamento nella sintesi · il ritorno allo sport non è l'unico esito, come gli autori stessi ricordano.",perte:"Verde: il quadricipite è il tuo innesto. La rassegna lo tratta come una delle opzioni ragionevoli, con buoni dati di ritorno anche negli scheletricamente immaturi, ma non lo dichiara superiore e non porta numeri propri. Dall'abstract non risulta che discuta i criteri di rientro, quindi non muove la T4. Cosa fare: nulla da cambiare; è una conferma di principio, non una prova."},{n:4,mono:"m-gray",dot:"green",sec:"res",j:"J Invest Surg",h:"Lussazione del ginocchio: lesione dell'arteria poplitea nello 0,38% dei ricoveri, con complicanze molto più frequenti",v:"Coorte retrospettiva su un database americano di riammissioni (2016-2020, Taiwan): circa 211.108 ricoveri per lussazione, lesione legamentosa o frattura periarticolare del ginocchio; lesione dell'arteria poplitea nello 0,38% (IC 95% 0,33-0,42%), con la lussazione come predittore più forte. Dopo appaiamento per propensity score, complicanze chirurgiche aOR 4,50 (IC 95% 3,40-5,97), riammissione a 30 giorni aOR 1,81 (IC 95% 1,21-2,70), degenza più lunga di 9,15 giorni (IC 95% 7,57-10,72).",ax:"Teng",date:"ott 2026",meta:"coorte retrospettiva su database amministrativo, livello III, circa 211.108 ricoveri",pmid:'42905570',doi:'10.1080/08941939.2026.2749354',journal:"Journal of investigative surgery : the official journal of the Academy of Surgical Research",authors:"Teng HG",design:"Coorte retrospettiva su adulti ricoverati con frattura periarticolare, lussazione o lesione legamentosa del ginocchio, dal Nationwide Readmissions Database 2016-2020; appaiamento per propensity score; esiti: degenza, complicanze, amputazioni, riammissioni a 30 e 90 giorni; regressioni multivariate con aOR. Letto solo l'abstract.",pop:"Stima nazionale di circa 211.108 ricoveri; il numero di pazienti con lesione dell'arteria poplitea non è riportato nell'abstract, solo la prevalenza ponderata dello 0,38%.",results:"Prevalenza ponderata della lesione dell'arteria poplitea 0,38% (IC 95% 0,33-0,42%). Dopo l'appaiamento: qualunque complicanza medica aOR 2,56 (IC 95% 1,88-3,49), complicanza chirurgica aOR 4,50 (IC 95% 3,40-5,97), insufficienza respiratoria aOR 3,59 (IC 95% 2,15-5,98), danno renale acuto aOR 2,71 (IC 95% 1,76-4,19), riammissione a 30 giorni aOR 1,81 (IC 95% 1,21-2,70), degenza più lunga di 9,15 giorni (IC 95% 7,57-10,72).",concl:"Gli autori: la lesione dell'arteria poplitea comporta una morbilità importante dopo un trauma grave del ginocchio e giustifica una valutazione vascolare completa, soprattutto nelle lussazioni; le associazioni non vanno lette come causali.",limits:"Database amministrativo: nessun dato su polsi, indice caviglia-braccio, tempo alla diagnosi o alla rivascolarizzazione · le complicanze del paziente con lesione vascolare riflettono anche la gravità del trauma, nonostante l'appaiamento · il codice del ginocchio raggruppa lussazioni, fratture e lesioni legamentose di gravità molto diversa.",perte:"Verde: le multilegamentose sono nella tua pratica. Il rischio assoluto è basso (0,38%) ma la lussazione è il predittore più forte, e il peso della complicazione è alto. Cosa fare: nulla da cambiare; è una conferma del principio di valutare sempre l'asse vascolare nella lussazione. Non muove le tensioni."},{n:5,mono:"m-gray",dot:"gray",sec:"res",j:"Zhongguo Xiu Fu Chong Jian Wai Ke Za Zhi",h:"LCA con legamento artificiale a doppio fascio: a 8,5 mesi pivot-shift negativo, ma lo studio è troppo breve e piccolo",v:"Studio comparativo retrospettivo cinese (Shenzhen): 45 pazienti, doppio fascio con legamento artificiale (16; over-the-top più fascio posterolaterale basso) contro fascio singolo over-the-top (29), controllo medio 8,5 mesi (6-13). Pivot-shift positivo in 0 contro 3 ginocchia di grado I (differenza non significativa); ritorno al livello di sport precedente più alto nel doppio fascio (p<0,05; percentuali non riportate); intervento più lungo.",ax:"Li, Yang, Zhuang, Lu",date:"ott 2026",meta:"studio comparativo retrospettivo, livello III, 45 pazienti (16 contro 29), controllo medio 8,5 mesi",pmid:'42896996',doi:'10.7507/1002-1892.202603058',journal:"Zhongguo xiu fu chong jian wai ke za zhi = Zhongguo xiufu chongjian waike zazhi = Chinese journal of reparative and reconstructive surgery",authors:"Li S, Yang K, Zhuang W, Lu W",design:"Analisi retrospettiva di rotture complete del LCA operate dall'ottobre 2022 all'ottobre 2025; gruppi assegnati in base alla misura anatomica e alla scelta della tecnica (non randomizzati); Lysholm, IKDC, Tegner, test di Lachman, cassetto e pivot-shift, ritorno allo sport, TC tridimensionale per i tunnel. Letto solo l'abstract.",pop:"45 pazienti con rottura completa del LCA: 29 nel fascio singolo, 16 nel doppio fascio; la distribuzione per sesso differisce fra i gruppi (p<0,05), età e punteggi di base simili.",results:"Controllo 6-13 mesi (media 8,5). Lachman e cassetto negativi in tutti; pivot-shift positivo in 3 ginocchia (tutte di grado I) del fascio singolo e in nessuna del doppio fascio (non significativo); ritorno allo sport più alto nel doppio fascio (p<0,05), percentuali non riportate; IKDC e Tegner migliorati in entrambi, Lysholm senza variazione significativa; distanza fra i tunnel oltre 5 mm alla TC; nessuna grave complicanza.",concl:"Gli autori: con una selezione anatomica rigorosa il doppio fascio senza conflitto mostra una tendenza favorevole sulla stabilità rotatoria e sul ritorno allo sport, ma richiede un'indicazione individualizzata.",limits:"Controllo medio di 8,5 mesi: troppo breve per la tenuta di un legamento artificiale · gruppi non randomizzati e di numerosità diversa, con differenza di sesso · il Lysholm non migliora in nessuno dei due gruppi, cosa che l'abstract non spiega.",perte:"Bianco: legamento artificiale e over-the-top, lontani dal tuo innesto di quadricipite o retto femorale. Nessuna indicazione per la tua pratica; l'unico spunto è la tecnica di tunnel che evita il conflitto, senza dati di durata. Nulla da fare. Non muove le tensioni."},{n:6,mono:"m-gray",dot:"gray",sec:"res",j:"J Orthop Res",h:"Estrusione del menisco: la mappatura circonferenziale su RM 3D è riproducibile, ma lo studio è di fattibilità",v:"Studio di fattibilità della Cleveland Clinic su 20 pazienti: l'estrusione misurata su ricostruzioni radiali di RM 3D ha variabilità bassa (intra-lettore DS 0,2 mm, coefficiente di ripetibilità 0,6 mm; fra lettori DS 0,5 mm, coefficiente di riproducibilità 1,4 mm) e concorda al 98% con la misura coronale standard al corpo. Differenze regionali fra menisco mediale e laterale e fra rotti e integri solo esplorative.",ax:"Vayansky, Altahawi, Ok, Lartey, Tosun, Obuchowski, Holden, Li, Winalski",date:"ott 2026",meta:"studio di fattibilità di imaging, livello non applicabile, 20 pazienti, 3 lettori",pmid:'42864603',doi:'10.1002/jor.70291',journal:"Journal of orthopaedic research : official publication of the Orthopaedic Research Society",authors:"Vayansky IR, Altahawi F, Ok AH, Lartey R, Tosun S, Obuchowski N, Holden W, Li X, Winalski CS",design:"Misura dell'estrusione meniscale su ricostruzioni multiplanari radiali di RM 3D fast spin-echo, da tre lettori indipendenti su 20 pazienti stratificati per rottura meniscale ed estrusione; ICC, coefficienti di ripetibilità e riproducibilità; confronto con la misura coronale 2D al corpo. Letto solo l'abstract.",pop:"20 pazienti stratificati per presenza di rottura meniscale e di estrusione; età, sesso e menisco per gruppo non riportati nell'abstract.",results:"Variabilità intra-lettore: DS media 0,2 mm, coefficiente di ripetibilità medio 0,6 mm. Variabilità fra lettori: DS media 0,5 mm, coefficiente di riproducibilità medio 1,4 mm. Concordanza al corpo con la misura coronale 2D: 98% entro 1,4 mm. Pattern regionali fra mediale e laterale e fra rotti e integri: analisi esplorativa, numeri non riportati.",concl:"Gli autori: la mappatura circonferenziale è fattibile e coerente fra lettori, e permette di caratterizzare lo spostamento regionale del menisco per studi futuri sul rapporto fra menisco e artrosi.",limits:"20 pazienti e nessun esito clinico: non dice se l'estrusione regionale predica qualcosa · il 98% di concordanza è entro la riproducibilità di 1,4 mm, una tolleranza larga rispetto alle soglie di 3 mm usate in clinica · analisi regionale esplorativa.",perte:"Bianco, ma utile per la T2b: l'estrusione è il parametro su cui insiste quella tensione, e questo lavoro mostra che la misura coronale al corpo concorda con la mappa circonferenziale (98%, tolleranza 1,4 mm), cioè che la misura che già usi è affidabile. Cosa fare: nulla da cambiare; la mappatura serve alla ricerca."},{n:7,mono:"m-gray",dot:"gray",sec:"res",j:"Front Bioeng Biotechnol",h:"Tendine della bandelletta ileotibiale come rinforzo nella riparazione del LCA: solo un modello a elementi finiti",v:"Modello a elementi finiti di un solo ginocchio (North Dakota State University): innesti della bandelletta ileotibiale larghi 10 mm e spessi 1, 1,5 o 2 mm in tunnel da 5, 6 e 7 mm. Con l'innesto da 2 mm nel tunnel da 5 mm lo stress massimo è 11,62 MPa e la deformazione 2,5%; con 1,5 mm in 6 mm 5,69 MPa e circa 1,1%, con lassità anteroposteriore 3,5 mm contro 3,2 mm del ginocchio intatto.",ax:"Vahidi Pashaki, Noonan, Katti, Katti",date:"set 2026",meta:"studio computazionale (elementi finiti), un solo modello da TC, nessun paziente",pmid:'42877147',doi:'10.3389/fbioe.2026.1913327',journal:"Frontiers in bioengineering and biotechnology",authors:"Vahidi Pashaki P, Noonan B, Katti KS, Katti DR",design:"Simulazione con elementi finiti (FEBio) su anatomia ricavata da una TC: nove combinazioni di spessore dell'innesto e diametro del tunnel; tibia bloccata, flessione di 30°, forza posteriore sul femore di 100 N; stress di von Mises e deformazione di Lagrange. Letto solo l'abstract.",pop:"Un solo ginocchio virtuale; nessun paziente e nessun cadavere.",results:"Stress e deformazione aumentano con innesti più spessi in tunnel più piccoli. 2 mm in 5 mm: stress massimo 11,62 MPa, deformazione 2,5%. 1,5 mm in 6 mm: deformazione massima circa 1,1%, stress principale massimo 5,69 MPa, lassità anteroposteriore 3,5 mm contro 3,2 mm del ginocchio intatto. Tunnel più larghi riducono sempre stress e deformazione; i picchi stanno presso il tunnel femorale. Intervalli di confidenza non applicabili.",concl:"Gli autori: il disaccordo fra innesto e tunnel compromette la meccanica della riparazione; la combinazione 1,5 mm con tunnel da 6 mm mostra stress e deformazione relativamente bassi con lassità vicina all'intatto.",limits:"Un solo modello paziente-specifico, osso rigido e carico statico di 100 N: non rappresenta l'anatomia, la fissazione né la guarigione reali · nessuna validazione su cadavere o su pazienti · la riparazione studiata è con un innesto biologico sottile, non il tuo innesto di quadricipite.",perte:"Bianco: modello computazionale su un solo ginocchio, senza paziente né cadavere. Il principio (innesto sottile in tunnel stretto = più stress) non riguarda il tuo innesto né una tua tecnica. Nulla da fare. Non muove le tensioni."},{n:8,mono:"m-gray",dot:"gray",sec:"res",j:"PLoS One",h:"Scelta dell'impianto nella revisione protesica asettica: mappa delle prove, nessuno studio di livello I",v:"Scoping review britannica (York) del tema «ginocchio problematico»: 7.096 articoli e 155 rapporti di registri; 121 articoli e 6 rapporti inclusi. Solo 22 studi (18%) hanno coorti di sole prime revisioni asettiche elettive; prevalgono serie retrospettive (45 su 121, 37%) e confronti retrospettivi (41, 34%), nessuno di livello I, e solo 5 studi (4%) hanno controllo medio o mediano di almeno 10 anni.",ax:"Tyas, Norman, Kolhe, Harden, Hewitt, Deehan, Baker",date:"ott 2026",meta:"scoping review (mappa delle prove, nessuna sintesi di effetto), 121 articoli e 6 rapporti di registri",pmid:'42905663',doi:'10.1371/journal.pone.0361040',journal:"PloS one",authors:"Tyas B, Norman J, Kolhe SN, Harden M, Hewitt C, Deehan D, Baker P",design:"Scoping review secondo Arksey e O'Malley e il manuale JBI, estensione PRISMA-ScR, registrata su OSF; ricerca in MEDLINE, Embase, CINAHL, CENTRAL e altre banche il 17 agosto 2026 (studi 2000-2026) più i rapporti annuali di 17 registri nazionali. Letto solo l'abstract.",pop:"121 articoli di ricerca e 6 rapporti di registri nazionali; 22 articoli (18%) riguardano esclusivamente prime revisioni asettiche elettive.",results:"Studi per livello: IV in 48 su 121 (40%), III in 46 (38%), nessuno di livello I. Tipi: serie di casi retrospettive 45 (37%), confronti retrospettivi 41 (34%). Controllo medio o mediano di almeno 10 anni in 5 studi (4%). Circa metà degli studi dagli Stati Uniti (58 su 102, 48%). Dimensioni dell'effetto non applicabili: è una mappa.",concl:"Gli autori: manca un'evidenza comparativa di alto livello sugli impianti da usare nella revisione protesica; indicano le lacune per la ricerca futura, in coerenza con la priorità della James Lind Alliance.",limits:"Scoping review: non valuta il rischio di bias né stima effetti, quindi non dice quale impianto scegliere · l'abstract è troncato prima delle raccomandazioni, che non ho letto · studi in inglese e metà dagli Stati Uniti.",perte:"Bianco: revisione protesica, fuori dalle tue tecniche. L'unico messaggio è che per la scelta dell'impianto di revisione le prove sono in gran parte retrospettive e di livello III-IV. Nulla da fare. Non muove le tensioni."}];
var SUGGQ=[{"k": "kol", "n": "Christoph Kittl (Università di Münster, Germania)", "w": "Germania: ultimo autore dello studio sul carico del LCA con varismo e angolo posterolaterale (PMID 42897444; nome e afferenza letti nei metadati PubMed), già comparso in elenchi di coautori nello storico. Corrispondenza tecnica con l'osteotomia correttiva e la protezione del LCA con la ricostruzione dell'angolo posterolaterale, cioè gli ambiti osteotomia e slope che esegui. Sostituisce Daniel B. F. Saris (nessun segnale dell'utente arrivato per farla ruotare)."}];
var BRIEF_TEXT="Venerdì 23 ottobre. Oggi otto lavori, nessuna scheda rossa e una arancione. Nessun richiamo di dispositivi nuovo rispetto a ieri, nessuna linea guida o consensus nuovo che tocchi la tua pratica e nessuna ritrattazione che ti riguardi. Il lavoro del giorno è una coorte retrospettiva giapponese, di Sapporo, sulla riparazione della radice posteriore del menisco mediale insieme all'osteotomia tibiale alta: cinquantaquattro ginocchia, pull-out transtibiale contro sutura all-inside, controllo da due a quattro anni; ho letto il testo completo. La continuità della radice è ripristinata nell'ottantanove per cento dei casi con la pull-out e nell'ottantotto virgola cinque con l'all-inside, e i punteggi di Lysholm sono novantasei e novantatré, senza differenze. Ma il rapporto di estrusione del menisco mediale sale da quarantanove virgola sei a sessantadue per cento con la pull-out e da quarantotto virgola otto a sessantotto virgola otto per cento con l'all-inside. La differenza fra i due gruppi non è significativa, ma la potenza dichiarata è del settantasei per cento solo per un effetto grande, e la coorte è sequenziale, senza un gruppo con la sola osteotomia. Il punto è che la continuità della sutura non è la funzione del menisco: tocca la tensione sull'estrusione, la seconda del tuo elenco. Poi sette lavori. Osteotomia tibiale alta, coorte giapponese di centottantuno ginocchia: nell'artrosi iniziale la sovracorrezione, con linea di carico dal settanta per cento in su, riduce il miglioramento del punteggio di articolazione dimenticata, mentre nell'artrosi avanzata l'allineamento non conta. Una rassegna narrativa sull'innesto nel crociato: l'autoinnesto è associato a più ritorno allo sport dell'alloinnesto, ma nessun autoinnesto, quadricipite compreso, è dimostrato superiore. Lesione dell'arteria poplitea: rara, zero virgola trentotto per cento dei ricoveri per trauma grave del ginocchio, ma con complicanze molto più frequenti, soprattutto dopo lussazione. Poi quattro lavori bianchi: il crociato con legamento artificiale a doppio fascio, studio troppo breve; la mappatura circonferenziale dell'estrusione meniscale su risonanza 3D, di fattibilità; un modello a elementi finiti sul rinforzo del crociato con la bandelletta ileotibiale; e la mappa delle prove sulla scelta dell'impianto nella revisione protesica, senza studi di livello uno. Tensioni: la seconda, sull'estrusione, ha un dato nuovo ma muto; le altre non si sono mosse.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Venerdì ventitré ottobre. Otto lavori, nessuna scheda rossa e una arancione. Nessun richiamo nuovo, nessun consensus nuovo sulla tua pratica e nessuna ritrattazione che ti riguardi."}, {"chi": "B", "t": "Qual è il lavoro del giorno?"}, {"chi": "A", "t": "Una coorte retrospettiva giapponese: cinquantaquattro ginocchia con riparazione della radice posteriore del menisco mediale e osteotomia tibiale alta, pull-out transtibiale contro all-inside, controllo da due a quattro anni."}, {"chi": "B", "t": "E cosa trova?"}, {"chi": "A", "t": "La continuità della radice è ripristinata in circa nove casi su dieci con entrambe le tecniche, e i punteggi di Lysholm sono molto alti, senza differenze fra le due."}, {"chi": "B", "t": "Quindi la sutura funziona."}, {"chi": "A", "t": "Tiene, ma l'estrusione del menisco mediale sale: da quarantanove virgola sei a sessantadue per cento con la pull-out e da quarantotto virgola otto a sessantotto virgola otto per cento con l'all-inside."}, {"chi": "B", "t": "La differenza fra le due tecniche è significativa?"}, {"chi": "A", "t": "No, ma la potenza dichiarata è del settantasei per cento solo per un effetto grande. Il disegno è sequenziale e un terzo circa dei pazienti è escluso."}, {"chi": "B", "t": "Per la mia pull-out transtibiale che cosa cambia?"}, {"chi": "A", "t": "Regge, ma la continuità della sutura non è la funzione del menisco. Vale la pena misurare l'estrusione sulla risonanza di controllo. Tocca la tensione sull'estrusione."}, {"chi": "B", "t": "Gli altri lavori?"}, {"chi": "A", "t": "Nell'osteotomia, la sovracorrezione riduce il recupero nell'artrosi iniziale. Poi una rassegna sull'innesto del crociato: nessun autoinnesto è dimostrato superiore, quadricipite compreso. E la lesione dell'arteria poplitea è rara, ma pesa molto dopo una lussazione."}];
